package net.fabricmc.fabric.api.event.lifecycle.v1; import net.minecraft.server.MinecraftServer; public final class ServerLifecycleEvents {public interface Listener{void on(MinecraftServer s);} public static class Event{public Listener cb; public void register(Listener l){cb=l;} public void fire(MinecraftServer s){cb.on(s);}} public static final Event SERVER_STARTED=new Event(),SERVER_STOPPING=new Event();}